/**
 * 中国天气网 · Surge 信息面板版
 * 数据来源：https://www.weather.com.cn，无需 Key
 * Surge 不支持 Egern Widget DSL；本版保留天气/黄历计算并输出纯文本 Panel。
 * ─────────────────────────────────────────────────────────────
 * 本版 = 原版天气组件 + 「每日宜忌」的 Surge 适配
 *   黄历引擎：农历 / 干支 / 建除十二神 / 值神(黄黑道) / 二十八宿 / 冲煞 / 五行 / 彭祖百忌 / 宜忌
 *             数据表取自 lunar-javascript（MIT © 6tail）移植版，覆盖 1900-2100
 *   新增 Env（主屏长按组件 → 编辑小组件 → Env，全部可选）：
 *     SHOW_YIJI   "0" = 关闭宜忌（完全恢复原版版式）
 *     YI_COUNT    宜 词条数上限（小 4 / 中 6 / 大 9，超出自动截断）
 *     JI_COUNT    忌 词条数上限（小 3 / 中 5 / 大 7）
 *   宜忌显示位置：
 *     小 = 农历·干支·建除·值神 一行 + 宜/忌 两条（两天预报精简为一行「明天」）
 *     中 = 表头时间行带农历 + 宜/忌 两条
 *     大 = 天气行下方黄历块（农历/干支/建除/值神/宿 + 冲煞/五行/彭祖 + 宜/忌）
 *   口径：宜忌按「日干支 × 月建」查表（与 lunar-javascript 同表同逻辑）；
 *        同日既宜又忌者以「忌」为准（通书惯例）。
 * ─────────────────────────────────────────────────────────────
 */

function surgeRequest(method, url, options) {
  const client = typeof $httpClient !== 'undefined' ? $httpClient : null;
  if (!client || typeof client[method.toLowerCase()] !== 'function') return Promise.reject(new Error('Surge $httpClient 不可用'));
  return new Promise((resolve, reject) => {
    const opts = Object.assign({ url }, options || {});
    client[method.toLowerCase()](opts, (error, response, body) => {
      if (error) return reject(new Error(String(error)));
      resolve({ status: response && (response.status || response.statusCode) || 0, text: String(body || '') });
    });
  });
}

function makeWeatherCtx() {
  return { http: { get: (url, options) => surgeRequest('GET', url, options).then((r) => ({ status: r.status, text: () => Promise.resolve(r.text) })) } };
}

